package io.github.describeadmin.codegen.generator;

import io.github.describeadmin.codegen.model.Layout;
import io.github.describeadmin.codegen.model.ModuleSpec;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertTrue;

class DdlGeneratorMutaGate1Test {

    @Test
    void escapesSingleQuotesInTableComment() {
        ModuleSpec spec = new ModuleSpec(
                "com.example.demo",
                "demo",
                "Demo",
                "biz_demo",
                "it's a demo",
                "/api/demo",
                Layout.values()[0],
                "default",
                List.of());

        String ddl = DdlGenerator.generate(spec);

        assertTrue(ddl.contains("COMMENT='it''s a demo';"), ddl);
    }
}

package io.github.describeadmin.codegen.generator;

import io.github.describeadmin.codegen.model.ModuleSpec;
import io.github.describeadmin.codegen.parser.SpecLoader;
import org.junit.jupiter.api.Test;

import java.nio.file.Path;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertTrue;

class DdlGeneratorMutaGate2Test {

    @Test
    void tableCommentSingleQuoteIsEscaped() throws Exception {
        ModuleSpec base = SpecLoader.load(Path.of("examples/project.yaml"));
        ModuleSpec spec = new ModuleSpec(
                base.basePackage(),
                base.module(),
                base.entity(),
                base.table(),
                "Bob's project",
                base.apiPrefix(),
                base.layout(),
                base.layoutOrigin(),
                List.of());

        String ddl = DdlGenerator.generate(spec);

        assertTrue(ddl.contains("COMMENT='Bob''s project';"), ddl);
    }
}

package io.github.describeadmin.codegen.generator;

import io.github.describeadmin.codegen.model.FieldSpec;
import io.github.describeadmin.codegen.model.ModuleSpec;
import io.github.describeadmin.codegen.parser.SpecLoader;
import org.junit.jupiter.api.Test;

import java.nio.file.Path;

import static org.assertj.core.api.Assertions.assertThat;

class DdlGeneratorMutaGate3Test {

    @Test
    void nullabilityOfEachFieldIsReflectedInColumnDefinition() throws Exception {
        ModuleSpec spec = SpecLoader.load(Path.of("examples/project.yaml"));
        String ddl = DdlGenerator.generate(spec);

        assertThat(spec.fields()).isNotEmpty();

        for (FieldSpec f : spec.fields()) {
            String line = null;
            for (String l : ddl.split("\n")) {
                if (l.strip().startsWith(f.column() + " ") && l.contains("COMMENT")) {
                    line = l;
                    break;
                }
            }
            assertThat(line).as("column line for %s", f.column()).isNotNull();

            if (f.nullable()) {
                assertThat(line).as(f.column()).contains(" NULL COMMENT");
                assertThat(line).as(f.column()).doesNotContain("NOT NULL");
            } else {
                assertThat(line).as(f.column()).contains("NOT NULL COMMENT");
            }
        }
    }
}

package io.github.describeadmin.codegen.generator;

import io.github.describeadmin.codegen.model.FieldSpec;
import io.github.describeadmin.codegen.model.ModuleSpec;
import io.github.describeadmin.codegen.parser.SpecLoader;
import org.junit.jupiter.api.Test;

import java.nio.file.Path;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class DdlGeneratorMutaGate4Test {

    @Test
    void columnTypeIsPaddedToElevenCharacters() throws Exception {
        ModuleSpec spec = SpecLoader.load(Path.of("examples/project.yaml"));
        assertFalse(spec.fields().isEmpty());

        String ddl = DdlGenerator.generate(spec);

        for (FieldSpec f : spec.fields()) {
            String expected = String.format("%-14s", f.column())
                    + " " + String.format("%-11s", f.sqlColumnType())
                    + " " + (f.nullable() ? "    NULL" : "NOT NULL")
                    + " COMMENT '";
            assertTrue(ddl.contains(expected),
                    "missing padded column definition: [" + expected + "]\n" + ddl);
        }
    }
}

